import {TUNING_LOCATION,tuningAligned} from './tuning-layout.js?v=0.8.1';
import {normalizeUpgrades,upgradeQuote,applyUpgradeVisuals} from './vehicle-upgrades.js?v=0.8.1';
export const PAINTS={default:{name:'Serienlack',color:null},graphite:{name:'Graphit',color:0x454c50},black:{name:'Schwarz',color:0x171c20},silver:{name:'Silber',color:0xa6afaf},white:{name:'Weiß',color:0xe5e2d9},blue:{name:'Tiefblau',color:0x23475e},green:{name:'Waldgrün',color:0x315247},burgundy:{name:'Bordeaux',color:0x713e45},sand:{name:'Champagner',color:0xb3a58a}};
export const RIMS={default:{name:'Serie'},classic:{name:'Klassik'},multi:{name:'Fine Multi-Spoke'},sport:{name:'Sport'},concave:{name:'Concave 5-Spoke'},split:{name:'Split 5-Spoke'},turbine:{name:'Turbine'}};
export const RIM_COLORS={silver:{name:'Silber',color:0xb5bdbc},anthracite:{name:'Anthrazit',color:0x50585e},black:{name:'Schwarz',color:0x20262b},bronze:{name:'Bronze',color:0x9c7950}};
export const TINTS={default:{name:'Serie',color:0x304953},smoke:{name:'Rauchgrau',color:0x21323c},dark:{name:'Dunkel',color:0x111d27}};
export const TRIMS={default:{name:'Serie',color:0x293238},black:{name:'Satinschwarz',color:0x141b20},graphite:{name:'Graphit',color:0x4b555a},silver:{name:'Satinsilber',color:0xa3aaa7}};
export const SPOILERS={none:{name:'Serie'},lip:{name:'Dezente Lippe'},touring:{name:'Touring-Spoiler'}};
export const TUNING_CATEGORIES={paint:{label:'LACK',name:'Lackierung',options:PAINTS},rims:{label:'FELGEN',name:'Felgendesign',options:RIMS},rimColor:{label:'FELGENFARBE',name:'Felgenfarbe',options:RIM_COLORS},tint:{label:'SCHEIBEN',name:'Scheibentönung',options:TINTS},trim:{label:'ZIERLEISTEN',name:'Zierleisten',options:TRIMS},spoiler:{label:'SPOILER',name:'Heckabschluss',options:SPOILERS}};
export const TUNING_DEFAULTS=Object.freeze({paint:'default',rims:'default',rimColor:'silver',tint:'default',trim:'default',spoiler:'none'});
export const TUNING_PRICES={paint:18000,rims:25000,rimColor:7000,tint:12000,trim:9000,spoiler:22000};
const catalogs=Object.fromEntries(Object.entries(TUNING_CATEGORIES).map(([key,category])=>[key,category.options]));
export function normalizeCustomization(c){return Object.fromEntries(Object.entries(catalogs).map(([k,options])=>[k,Object.hasOwn(options,c?.[k])?c[k]:TUNING_DEFAULTS[k]]));}
export function validCustomization(c){return !!c&&Object.entries(catalogs).every(([k,options])=>(!Object.hasOwn(c,k)&&['tint','trim','spoiler'].includes(k))||(typeof c[k]==='string'&&Object.hasOwn(options,c[k])));}
export function tuningQuote(original,next){if(!validCustomization(next))return null;const old=normalizeCustomization(original),selected=normalizeCustomization(next),changes=Object.keys(catalogs).filter(k=>old[k]!==selected[k]);return {changes,total:changes.reduce((n,k)=>n+TUNING_PRICES[k],0)};}
export function tuningVehicle(s){if(s.inside||s.riding||s.transit||s.vehicleService||s.scavenge?.action||s.job?.fieldAction||s.job?.interaction||s.dailyLife?.action||s.workshop?.active?.action||Math.hypot(s.position.x-TUNING_LOCATION.x,s.position.z-TUNING_LOCATION.z)>3)return null;return (s.fleet||[]).find(tuningAligned)||null;}
export function workshopQuote(vehicle,appearance,upgrades=normalizeUpgrades(vehicle.upgrades)){const visual=tuningQuote(vehicle.customization,appearance),parts=upgradeQuote(vehicle,upgrades);if(!visual||!parts)return null;return {changes:visual.changes,upgradeChanges:parts.changes,total:visual.total+parts.total};}
export function purchaseTuning(model,uid,next,upgrades){const v=tuningVehicle(model.s);if(!v||v.uid!==uid)return false;const selected=upgrades===undefined?normalizeUpgrades(v.upgrades):upgrades,quote=workshopQuote(v,next,selected);if(!quote?.total||!Number.isSafeInteger(model.s.money)||model.s.money<quote.total||!model.spend(quote.total))return false;v.customization=normalizeCustomization(next);v.upgrades=normalizeUpgrades(selected);model.emit('WERKFORM · Fahrzeugumbau übernommen.','success');return true;}
// Preview is mesh-only. Autosaves always contain the last purchased appearance.
export function applyVehicleCustomization(mesh,vehicle,preview=null){if(!mesh?.userData.paintMaterial||vehicle.id==='bike')return;const u=mesh.userData,c=normalizeCustomization(preview||vehicle.customization),key=Object.values(c).join('|');if(u.customizationKey===key)return;u.defaultPaint??=u.paintMaterial.color.getHex();u.paintMaterial.color.setHex(PAINTS[c.paint].color??u.defaultPaint);u.rimMaterial.color.setHex(RIM_COLORS[c.rimColor].color);for(const [style,parts] of Object.entries(u.rimStyleGroups||{}))for(const part of parts)part.visible=style===c.rims;if(u.glassMaterial)u.glassMaterial.color.setHex(TINTS[c.tint].color);if(u.trimMaterial){u.trimMaterial.color.setHex(TRIMS[c.trim].color);u.trimMaterial.metalness=c.trim==='silver'?.55:.05;u.trimMaterial.roughness=c.trim==='silver'?.42:.83;}for(const [style,part] of Object.entries(u.spoilerGroups||{}))part.visible=style===c.spoiler;u.customizationKey=key;}
export function startTuningPreview(mesh,vehicle){const draft=normalizeCustomization(vehicle.customization);return {uid:vehicle.uid,vehicle,mesh,draft,upgrades:normalizeUpgrades(vehicle.upgrades),section:'power',tab:'paint'};}
export function cancelTuningPreview(session){if(session){applyVehicleCustomization(session.mesh,session.vehicle);applyUpgradeVisuals(session.mesh,session.vehicle);}}
